import csv
with open(VALUES_CSV) as f:
    rows = list(csv.DictReader(f))
vals = [(r['timestamp'], float(r['value'])) for r in rows if r['timeseries_id']=='03f8d175-8f4f-5a5c-8017-4cac0978dde8']
for t,v in vals:
    if t.startswith('2018-10-17'):
        print(t,v)
target_val = None
for t,v in vals:
    if t=='2018-10-17T09:00:00':
        target_val=v
mx = max(v for t,v in vals)
print("target",target_val,"max",mx,"ratio",target_val/mx)
